import base64
import hashlib
import os
import secrets
from dataclasses import dataclass
from typing import Dict, Optional
from urllib.parse import urlencode, urlparse, parse_qs

import requests


@dataclass
class PKCEAuthConfig:
    client_id: str
    redirect_uri: str
    auth_domain: str
    scope: str = "openid profile email"
    audience: Optional[str] = None
    response_type: str = "code"
    response_mode: Optional[str] = None
    token_endpoint: Optional[str] = None


class PKCEAuthFlow:
    """
    PKCE Authorization Code flow for public clients against Auth0 hosted authorization server.

    Uses Auth0's /authorize and /oauth/token endpoints.
    """

    def __init__(self, config: PKCEAuthConfig):
        self.config = config
        self.code_verifier = self._generate_code_verifier()
        self.code_challenge = self._generate_code_challenge(self.code_verifier)
        self.state = secrets.token_urlsafe(32)

    @staticmethod
    def _generate_code_verifier() -> str:
        # RFC 7636: high-entropy cryptographic random string, 43-128 chars.
        return base64.urlsafe_b64encode(os.urandom(64)).decode("ascii").rstrip("=")

    @staticmethod
    def _generate_code_challenge(code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return base64.urlsafe_b64encode(digest).decode("ascii").rstrip("=")

    def get_authorization_url(self, extra_params: Optional[Dict[str, str]] = None) -> str:
        params = {
            "client_id": self.config.client_id,
            "response_type": self.config.response_type,
            "redirect_uri": self.config.redirect_uri,
            "scope": self.config.scope,
            "state": self.state,
            "code_challenge": self.code_challenge,
            "code_challenge_method": "S256",
        }
        if self.config.audience:
            params["audience"] = self.config.audience
        if self.config.response_mode:
            params["response_mode"] = self.config.response_mode
        if extra_params:
            params.update(extra_params)

        return f"https://{self.config.auth_domain}/authorize?{urlencode(params)}"

    def validate_callback(self, callback_url: str) -> str:
        parsed = urlparse(callback_url)
        query = parse_qs(parsed.query)

        returned_state = query.get("state", [None])[0]
        if returned_state != self.state:
            raise ValueError("Invalid state returned in callback URL")

        error = query.get("error", [None])[0]
        if error:
            description = query.get("error_description", [""])[0]
            raise RuntimeError(f"Authorization error: {error} {description}".strip())

        code = query.get("code", [None])[0]
        if not code:
            raise ValueError("Authorization code not found in callback URL")

        return code

    def exchange_code_for_tokens(self, authorization_code: str) -> Dict[str, str]:
        token_url = self.config.token_endpoint or f"https://{self.config.auth_domain}/oauth/token"

        payload = {
            "grant_type": "authorization_code",
            "client_id": self.config.client_id,
            "code": authorization_code,
            "redirect_uri": self.config.redirect_uri,
            "code_verifier": self.code_verifier,
        }

        response = requests.post(
            token_url,
            json=payload,
            timeout=30,
            headers={"Accept": "application/json"},
        )
        response.raise_for_status()
        return response.json()

    def login_from_callback(self, callback_url: str) -> Dict[str, str]:
        code = self.validate_callback(callback_url)
        return self.exchange_code_for_tokens(code)
